# exec'd from build.py; defines free calculator pages
SUB="https://thetapelog.beehiiv.com/subscribe"
TCSS="<style>.calc{background:#f4f7fa;border-radius:10px;padding:16px;margin:16px 0}.calc label{display:block;margin:8px 0 2px;font-weight:600}.calc input,.calc select{font:inherit;padding:8px;width:100%;max-width:280px;border:1px solid #c9d3dd;border-radius:6px}.out{background:#fff;border:1px solid #dde3ea;border-radius:8px;padding:12px;margin-top:12px;font-size:1.05em}</style>"
def tool(slug,title,desc,h1,intro,form,js,faqs,extra=""):
    body=f"""{TCSS}<h1>{h1}</h1><p>{intro}</p><div class="calc" id="c">{form}<div class="out" id="o">Enter values above.</div></div>
<script>(function(){{const v=id=>parseFloat(document.getElementById(id).value);const f=n=>isFinite(n)?n.toLocaleString(undefined,{{maximumFractionDigits:2}}):'–';function run(){{const o=document.getElementById('o');{js}}}document.querySelectorAll('#c input,#c select').forEach(e=>e.addEventListener('input',run));run();}})();</script>
{extra}<p class="note">Want this calculated automatically from your real trades? <a href="{LITE}">TapeLog Lite</a> is free, and the <a href="{FULL}">full kit ($24 one-time)</a> imports DAS Trader Pro and Robinhood CSVs. Get one trading-stats lesson a week in <a href="{SUB}">The TapeLog newsletter</a> (free).</p>
<h2>FAQ</h2>{faq_html(faqs)}<p class="small">Educational calculator only. Not financial advice. Runs entirely in your browser; nothing is sent anywhere. More <a href="/tapelog/tools/">free trading calculators</a>.</p>"""
    page(f"/tools/{slug}/",title,desc,body,[faq_ld(faqs),{"@context":"https://schema.org","@type":"WebApplication","name":h1,"applicationCategory":"FinanceApplication","operatingSystem":"Any (web browser)","offers":{"@type":"Offer","price":"0","priceCurrency":"USD"},"url":f"{BASE}/tools/{slug}/"}])
    TOOLS.append((slug,h1,desc))
TOOLS=[]
def inp(i,l,v,s="any"): return f'<label for="{i}">{l}</label><input id="{i}" type="number" step="{s}" value="{v}">'
tool("position-size-calculator","Position Size Calculator for Day Traders (Risk-Based, Free) | TapeLog","Free position size calculator: enter account size, risk %, entry and stop to get the share count, dollar risk and position value. Works for longs and shorts.","Position size calculator",
"Size every trade from your stop, not your gut. Enter your account, the percent you're willing to risk, and your entry and stop.",
inp("a","Account size ($)",25000)+inp("r","Risk per trade (%)",1)+inp("e","Entry price ($)",10)+inp("s","Stop price ($)",9.7)+inp("m","Max position as % of account (optional cap)",100),
"const risk=v('a')*v('r')/100,per=Math.abs(v('e')-v('s'));if(!(per>0)){o.textContent='Entry and stop must differ.';return}let sh=Math.floor(risk/per);const cap=Math.floor(v('a')*v('m')/100/v('e'));let note='';if(sh>cap){sh=cap;note=' (capped by max position %)'}o.innerHTML=`<b>${sh.toLocaleString()} shares</b>${note}<br>Dollar risk: $${f(sh*per)} (target $${f(risk)})<br>Risk per share: $${f(per)}<br>Position value: $${f(sh*v('e'))} (${f(sh*v('e')/v('a')*100)}% of account)<br>Direction: ${v('s')<v('e')?'Long':'Short'}`",
[("How do I calculate position size?","Shares = (account size × risk %) ÷ |entry − stop|. With a $25,000 account, 1% risk ($250) and a $0.30 stop distance, you buy 833 shares."),
("What percent should I risk per trade?","Many traders risk 0.5% to 2% of their account per trade so a losing streak doesn't cause a large drawdown. Choose what fits your own plan; this is not advice."),
("Does this work for short trades?","Yes. Put the stop above the entry and the calculator uses the absolute distance.")])
tool("risk-reward-calculator","Risk Reward & R-Multiple Calculator (Free) | TapeLog","Free risk/reward and R-multiple calculator: enter entry, stop, target and exit to get R:R ratio, R-multiple of the result, and breakeven win rate.","Risk/reward &amp; R-multiple calculator",
"Measure every trade in R, the amount you risked. Enter your plan (entry, stop, target) and, optionally, where you actually exited.",
inp("e","Entry ($)",10)+inp("s","Stop ($)",9.7)+inp("t","Target ($)",10.9)+inp("x","Actual exit ($, optional)",10.45),
"const risk=v('e')-v('s'),rew=v('t')-v('e');if(!risk){o.textContent='Entry and stop must differ.';return}const rr=rew/risk,rx=(v('x')-v('e'))/risk;o.innerHTML=`Planned reward:risk = <b>${f(rr)} : 1</b><br>Breakeven win rate at this R:R: <b>${f(100/(1+rr))}%</b><br>`+(isFinite(rx)?`Actual result: <b>${f(rx)}R</b>`:'')",
[("What is an R-multiple?","R is your initial risk per share (entry minus stop). A trade's R-multiple is its profit or loss divided by that risk, so +2R means you made twice what you risked."),
("What is a good risk/reward ratio?","There's no single answer. A 1:1 ratio needs better than a 50% win rate to profit; 2:1 needs better than about 33%. Your win rate and R:R together determine expectancy."),
("How do I calculate breakeven win rate from R:R?","Breakeven win rate = 1 ÷ (1 + R:R). At 2:1, that's 1 ÷ 3 ≈ 33.3%, before fees.")])
tool("profit-factor-expectancy-calculator","Profit Factor & Expectancy Calculator for Traders (Free) | TapeLog","Free profit factor and expectancy calculator: enter win rate, average win and average loss (or gross profit/loss) to get profit factor, expectancy per trade and payoff ratio.","Profit factor &amp; expectancy calculator",
"Find out whether your trading has an edge. Enter your win rate and average win and loss from your journal.",
inp("w","Win rate (%)",45)+inp("aw","Average win ($)",180)+inp("al","Average loss ($, positive number)",110)+inp("n","Number of trades",100,"1"),
"const p=v('w')/100,aw=v('aw'),al=Math.abs(v('al')),n=v('n');const gp=p*n*aw,gl=(1-p)*n*al,ex=p*aw-(1-p)*al;o.innerHTML=`Profit factor: <b>${f(gp/gl)}</b><br>Expectancy: <b>$${f(ex)} per trade</b> (${f(ex/al)}R if avg loss ≈ 1R)<br>Payoff ratio (avg win ÷ avg loss): ${f(aw/al)}<br>Projected net over ${n} trades: $${f(ex*n)}<br>${ex>0?'Positive expectancy.':'Negative expectancy: losses outweigh wins.'}`",
[("What is profit factor?","Profit factor = gross profit ÷ absolute gross loss. Above 1.0 means winners earned more than losers lost; 1.5 or higher is often considered solid, but sample size matters."),
("What is trading expectancy?","Expectancy = (win rate × average win) − (loss rate × average loss). It's the average amount you make or lose per trade."),
("Can I be profitable with a low win rate?","Yes, if your average win is large enough relative to your average loss. A 35% win rate with a 2.5 payoff ratio has positive expectancy.")])
tool("win-rate-breakeven-calculator","Breakeven Win Rate Calculator (by Risk:Reward & Fees) | TapeLog","Free breakeven win rate calculator: see the minimum win rate you need to break even for your average win, average loss and per-trade fees.","Breakeven win rate calculator",
"What win rate do you actually need? Enter your average win and loss and your round-trip fees.",
inp("aw","Average win ($)",150)+inp("al","Average loss ($, positive)",100)+inp("fe","Fees per round trip ($)",2)+inp("w","Your current win rate (%, optional)",42),
"const aw=v('aw')-v('fe'),al=Math.abs(v('al'))+v('fe');const be=al/(aw+al)*100;const w=v('w');o.innerHTML=`Breakeven win rate: <b>${f(be)}%</b> (after fees)<br>`+(isFinite(w)?`Your win rate ${f(w)}% is <b>${w>be?f(w-be)+' points above':f(be-w)+' points below'}</b> breakeven.`:'')",
[("How do I calculate breakeven win rate?","Breakeven win rate = average loss ÷ (average win + average loss), with fees subtracted from wins and added to losses."),
("Why do fees matter so much?","Small-account and scalping traders often have small average wins, so a few dollars of commission and ECN fees per trade can raise the breakeven win rate by several points."),
("Is win rate the most important stat?","No. Win rate means nothing without your average win and loss. Use profit factor and expectancy for the full picture.")])
tool("drawdown-recovery-calculator","Drawdown Recovery Calculator: Gain Needed to Recover a Loss | TapeLog","Free drawdown recovery calculator: see the percentage gain needed to recover from a drawdown, and how many losing trades in a row cause it at your risk per trade.","Drawdown recovery calculator",
"Losses compound against you. See the gain needed to get back to even, and how fast a losing streak digs the hole.",
inp("d","Drawdown (%)",20)+inp("r","Risk per trade (%)",1)+inp("k","Losing streak length (trades)",10,"1"),
"const d=v('d')/100,r=v('r')/100,k=v('k');const need=(1/(1-d)-1)*100,streak=(1-Math.pow(1-r,k))*100,tr=Math.log(1-d)/Math.log(1-r);o.innerHTML=`Gain needed to recover a ${f(d*100)}% drawdown: <b>${f(need)}%</b><br>A ${k}-trade losing streak at ${f(r*100)}% risk = <b>${f(streak)}% drawdown</b><br>Consecutive losses to reach ${f(d*100)}% drawdown at this risk: ${f(tr)}`",
[("How much gain do I need to recover a drawdown?","Required gain = 1 ÷ (1 − drawdown) − 1. A 20% loss needs a 25% gain; a 50% loss needs 100%."),
("How do I limit drawdowns?","Risk a fixed small percent per trade, set a daily max-loss rule, and review your journal for the setups and times that cause the biggest losses."),
("What is max drawdown?","The largest peak-to-trough decline in your equity curve. TapeLog's full kit computes it automatically from your trades.")])
pdt_form='<label for="d">Day trades made in the last 5 business days (including today)</label><input id="d" type="number" step="1" value="2"><label for="p">Does your broker still enforce the PDT rule?</label><select id="p"><option value="1">Yes</option><option value="0">No / not sure</option></select><label for="eq">Account equity ($)</label><input id="eq" type="number" step="any" value="8000">'
tool("pdt-day-trade-calculator","PDT Day Trade Calculator: How Many Day Trades Do I Have Left? (2026) | TapeLog","Free PDT calculator: enter your day trades in the last 5 business days and account equity to see how many day trades you have left, with FINRA's 2026 PDT rule change.","PDT day trade calculator",
"How many day trades do you have left this week? Enter your count from the rolling 5-business-day window.",
pdt_form,"const d=parseInt(document.getElementById('d').value)||0,p=document.getElementById('p').value==='1',eq=v('eq');if(!p){o.innerHTML='Your broker may no longer apply the PDT limit after FINRA\\'s 2026 rule change. Check your broker\\'s current policy.';return}if(eq>=25000){o.innerHTML='<b>Equity is at or above $25,000:</b> the traditional PDT limit does not restrict you (keep equity above $25k).';return}const left=Math.max(0,3-d);o.innerHTML=`Day trades left in the window: <b>${left}</b><br>`+(left===0?'A 4th day trade would likely flag the account as a pattern day trader.':'Your oldest day trade drops off after 5 business days.')",
[("How many day trades can I make under $25k?","Under the traditional PDT rule, 3 day trades in any rolling 5-business-day window in a margin account. A 4th flags the account if day trades exceed 6% of total trades."),
("Is the PDT rule still in effect in 2026?",PDT_NOTE),
("What counts as a day trade?","Opening and closing the same position in the same security on the same day in a margin account.")],
f'<p class="small">See also the <a href="/tapelog/pdt-day-trade-counter/">PDT day-trade counter in the spreadsheet</a>.</p>')
hub="<h1>Free trading calculators</h1><p>Free, private, in-browser calculators for day traders. No sign-up.</p><ul>"+"".join(f'<li><a href="/tapelog/tools/{s}/">{h}</a>: {html.escape(d)}</li>' for s,h,d in TOOLS)+f'</ul><p>Get one trading-stats lesson a week: <a href="{SUB}">subscribe to The TapeLog (free)</a>.</p>'
HUBFAQ=[("Are these calculators free?","Yes. They run in your browser and send no data anywhere."),("Which calculator should I start with?","Start with the position size calculator to set risk, then use the profit factor & expectancy calculator on your journal stats.")]
page("/tools/","Free Trading Calculators: Position Size, R:R, Profit Factor, PDT | TapeLog","Free day-trading calculators: position size, risk/reward and R-multiple, profit factor and expectancy, breakeven win rate, drawdown recovery and PDT day trades left.",hub+"<h2>FAQ</h2>"+faq_html(HUBFAQ),[faq_ld(HUBFAQ)])
